<script setup lang="ts">import {ref} from 'vue';import {readUser,clear} from './stores/session';import {useWorkspace} from './hooks/useWorkspace';import {navigation} from './router/navigation';import {ROLES} from './constants/enums';import Login from './pages/Login.vue';import Overview from './pages/Overview.vue';import Datasets from './pages/Datasets.vue';import Profiles from './pages/Profiles.vue';import Scenarios from './pages/Scenarios.vue';import Results from './pages/Results.vue';import Reviews from './pages/Reviews.vue';import Notice from './components/common/Notice.vue';const user=ref(readUser()),page=ref(location.hash.slice(1)||'overview');const {data,error,loading,refresh}=useWorkspace(user);function go(value:string){page.value=value;location.hash=value;window.scrollTo(0,0)}function logout(){clear();user.value=null};
</script><template><Login v-if="!user" @login="user=$event"/><div v-else class="shell"><header class="topbar"><div class="brand"><span class="brand-glyph">岫</span><div>云岫实验室<small>收样窗口容量预演</small></div></div><div class="topbar-label">OPERATIONS / CAPACITY NOTEBOOK</div><div class="user"><span>{{ROLES[user.role]}}</span><small>{{user.email}}</small><button @click="logout">退出</button></div></header><nav class="navigation"><button v-for="n in navigation" :key="n.id" :class="{active:page===n.id}" @click="go(n.id)"><i>{{n.code}}</i>{{n.label}}</button></nav><main class="workspace"><Notice v-if="error" error>{{error}}<button class="text-button" @click="refresh">重试</button></Notice><p v-if="loading">正在读取预演资料…</p><template v-else><Overview v-if="page==='overview'" :data="data" @go="go"/><Datasets v-else-if="page==='datasets'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh"/><Profiles v-else-if="page==='profiles'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh"/><Scenarios v-else-if="page==='scenarios'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh" @go="go"/><Results v-else-if="page==='results'" :data="data"/><Reviews v-else :data="data" :can-write="user.role!=='viewer'" :is-admin="user.role==='admin'" :refresh="refresh"/></template><footer>云岫实验室 · 模拟容量研究<span>分钟口径 / 固定种子 / 人工复核</span></footer></main></div></template>
